# Raw vector layers from /data/gold/atlas_4326/
# Generated for TSIRD mapserver - canonical EPSG:4326 shapefile atlas
#
# CHANGELOG 2026-02-21:
# - Fixed all OGR DATA field names (now correctly reference actual shapefile layer names)
# - Removed all PROJECTION blocks (data is canonically EPSG:4326, MAP-level projection handles reprojection)
# - Verified all CONNECTION paths map to existing files in /data/gold/atlas_4326/
#
# GetFeatureInfo Metadata Strategy:
# - GetFeatureInfo is enabled via METADATA keywords: wms_include_items, gml_include_items, wms_feature_info_mime_type
# - Each layer includes TEMPLATE "dummy.html" for HTML output format
# - The DUMP keyword (unsupported in MapServer 8.6.0) has been removed; METADATA + TEMPLATE provide feature attributes
# - Each layer includes curated field lists for meaningful attribute queries
# - See docs/atlas/vector_featureinfo_plan.yml for field curation rationale
#
# Projection Handling:
# - All data is EPSG:4326 (WGS 84 geographic)
# - MAP-level PROJECTION is EPSG:4326, no layer-level projection blocks needed
# - OGR layers do not have PROJECTION declarations (relies on MAP-level projection)
# - MapServer automatically handles CRS conversion from EPSG:4326 as needed

LAYER
  NAME "ethiopia_zones"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE OGR
  CONNECTION "/data/gold/atlas_4326/bound03.shp"
  DATA "bound03"
  LABELITEM "ZONES"
  LABELMAXSCALEDENOM 3000000
  METADATA
    "wms_title" "Ethiopia - Zones (pre-91)"
    "wms_srs" "EPSG:3857 EPSG:4326"
    "wms_enable_request" "*"
    "wms_queryable" "true"
    "wms_feature_info_mime_type" "text/plain"
    "gml_include_items" "ZONES,AREA,PERIMETER,ETZONES01C,ETZONES01C_1"
    "wms_include_items" "ZONES,AREA,PERIMETER,ETZONES01C,ETZONES01C_1"
  END
  TEMPLATE "dummy.html"
  CLASS
    NAME "Zones"
    STYLE
      COLOR 171 170 107
      OUTLINECOLOR 0 0 0
      OPACITY 50
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
    END
  END
END

