LAYER
  NAME "ethiopia_woredas"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE OGR
  CONNECTION "/data/gold/atlas_4326/ethiopia/EthioWoredasNew.shp"
  DATA "EthioWoredasNew"
  LABELITEM "W_NAME"
  LABELMAXSCALEDENOM 2000000
  LABELMINSCALEDENOM 100000
  METADATA
    "wms_title" "Ethiopia - Woredas"
    "wms_srs" "EPSG:3857 EPSG:4326"
    "wms_enable_request" "*"
    "wms_queryable" "true"
    "wms_feature_info_mime_type" "text/plain"
    "gml_include_items" "W_NAME,REGION_R2I,Area_km2,Pop_04,Pop_Den,Admin_Unit"
    "wms_include_items" "W_NAME,REGION_R2I,Area_km2,Pop_04,Pop_Den,Admin_Unit"
  END
  TEMPLATE "dummy.html"
  CLASS
    NAME "Woredas"
    STYLE
      COLOR 240 240 230
      OUTLINECOLOR 80 80 80
      WIDTH 0.5
      OPACITY 40
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 1
      FONT "arial"
      TYPE TRUETYPE
      SIZE 8
      POSITION AUTO
      PARTIALS FALSE
    END
  END
END

