    "wms_include_items" "TABIA,WEREDA,ZONES,SQ_KM,HECTARES,DENSITY"
  END
  TEMPLATE "dummy.html"
  # Graduated by area (HECTARES)
  CLASS
    NAME "Small (<500 ha)"
