    STYLE
      COLOR 250 250 240
      OUTLINECOLOR 120 120 120
      OPACITY 60
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 1
      FONT "arial"
      TYPE TRUETYPE
      SIZE 8
      POSITION AUTO
      PARTIALS FALSE
    END
  END
  CLASS
    NAME "Medium (500-1000 ha)"
    EXPRESSION ([HECTARES] >= 500 AND [HECTARES] < 1000)
    STYLE
      COLOR 230 230 220
      OUTLINECOLOR 100 100 100
      OPACITY 70
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 1
      FONT "arial"
      TYPE TRUETYPE
      SIZE 8
      POSITION AUTO
      PARTIALS FALSE
    END
  END
  CLASS
    NAME "Large (>1000 ha)"
    EXPRESSION ([HECTARES] >= 1000)
    STYLE
      COLOR 210 210 200
      OUTLINECOLOR 80 80 80
      OPACITY 80
    END
    LABEL
      COLOR 50 50 50
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 1
      FONT "arial"
      TYPE TRUETYPE
      SIZE 8
      POSITION AUTO
      PARTIALS FALSE
    END
  END
END

