LAYER
  NAME "tigray_towns"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE OGR
  CONNECTION "/data/gold/atlas_4326/Tigray_Towns.shp"
  DATA "Tigray_Towns"
  LABELITEM "TOWN_NAME"
  LABELMAXSCALEDENOM 2000000
  METADATA
    "wms_title" "Tigray - Towns (by Population)"
    "wms_srs" "EPSG:3857 EPSG:4326"
    "wms_enable_request" "*"
    "wms_queryable" "true"
    "wms_feature_info_mime_type" "text/plain"
    "gml_include_items" "TOWN_NAME,WEREDA,REGION,ZONES,POP,POPTOT"
    "wms_include_items" "TOWN_NAME,WEREDA,REGION,ZONES,POP,POPTOT"
  END
  TEMPLATE "dummy.html"
  # Graduated symbols by population
  CLASS
    NAME "0 - 50,000"
    EXPRESSION ([POPTOT] <= 50000)
    STYLE
      SYMBOL "circle"
      SIZE 5
      COLOR 255 203 197
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "50,000 - 80,000"
    EXPRESSION ([POPTOT] > 50000 AND [POPTOT] <= 80000)
    STYLE
      SYMBOL "circle"
      SIZE 7
      COLOR 255 175 169
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 9
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "80,000 - 120,000"
    EXPRESSION ([POPTOT] > 80000 AND [POPTOT] <= 120000)
    STYLE
      SYMBOL "circle"
      SIZE 9
      COLOR 255 144 141
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 10
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "120,000 - 200,000"
    EXPRESSION ([POPTOT] > 120000 AND [POPTOT] <= 200000)
    STYLE
      SYMBOL "circle"
      SIZE 12
      COLOR 255 97 94
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial"
      TYPE TRUETYPE
      SIZE 10
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
  CLASS
    NAME "> 200,000"
    EXPRESSION ([POPTOT] > 200000)
    STYLE
      SYMBOL "circle"
      SIZE 15
      COLOR 255 31 26
      OUTLINECOLOR 100 50 50
    END
    LABEL
      COLOR 132 31 31
      OUTLINECOLOR 255 255 255
      OUTLINEWIDTH 2
      FONT "arial-bold"
      TYPE TRUETYPE
      SIZE 11
      POSITION AUTO
      PARTIALS FALSE
      BUFFER 4
    END
  END
END

